class Palindrome:
    def __init__(self, string: str):
        self.string = string

    def is_palindrome(self) -> bool:
        """ Test if given string is a palindrome """
        return self.string == self.string[::-1]

    def make_palindrome(self) -> str:
        """ Find the shortest palindrome that begins with a supplied string """
        if not self.string:
            return ''

        for i in range(len(self.string), -1, -1):
            if self.is_palindrome(self.string[i:]):
                palindromic_suffix = self.string[i:]
                break

        prefix = self.string[:len(self.string) - len(palindromic_suffix)]
        reversed_prefix = prefix[::-1]

        palindrome = palindromic_suffix + reversed_prefix

        return palindrome

# Example usage:
palindrome = Palindrome('cata')
print(palindrome.make_palindrome())  # Output: catac

